use crate::{CoreError,CoreResult,Path,PathLocation,Point2,Scalar,Tolerance,flatten_path,path_length};
#[derive(Clone,Copy,Debug,PartialEq)]pub struct ClosestPointResult{pub point:Point2,pub distance:Scalar,pub distance_squared:Scalar,pub location:PathLocation}
fn closest_line(a:Point2,b:Point2,p:Point2)->(Point2,Scalar){let d=b-a;let dd=d.dot(d);if dd==0.0{return(a,0.0)}let t=((p-a).dot(d)/dd).clamp(0.0,1.0);(a+d*t,t)}
pub fn closest_point(path:&Path,p:Point2,tol:Tolerance)->CoreResult<ClosestPointResult>{if path.is_empty(){return Err(CoreError::DegenerateOperation)}let flat=flatten_path(path,tol)?;let total=path_length(path,tol)?;let mut best=None;let mut distance_acc=0.0;for(si,sub)in flat.iter().enumerate(){for(gi,w)in sub.points.windows(2).enumerate(){let a=w[0];let b=w[1];let len=a.distance_to(b);let(q,t)=closest_line(a,b,p);let ds=q.distance_squared_to(p);if best.map_or(true,|(v,_,_,_,_,_)|(ds<v)){best=Some((ds,q,si,gi,t,distance_acc+t*len));}distance_acc+=len}}let(ds,q,si,gi,t,d)=best.ok_or(CoreError::DegenerateOperation)?;Ok(ClosestPointResult{point:q,distance:ds.sqrt(),distance_squared:ds,location:PathLocation{subpath_index:si,segment_index:gi,t,distance:d.min(total)}})}
